# Hash/size/physical stability checks below apply only to immutable metadata source files.
def exact_file(path,digest,size):
 p=Path(path);pre=p.lstat();assert stat.S_ISREG(pre.st_mode) and not stat.S_ISLNK(pre.st_mode) and pre.st_size==size
 fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW)
 with os.fdopen(fd,'rb') as stream:
  opened=os.fstat(stream.fileno());assert (opened.st_dev,opened.st_ino,opened.st_size,opened.st_mtime_ns,opened.st_ctime_ns)==(pre.st_dev,pre.st_ino,pre.st_size,pre.st_mtime_ns,pre.st_ctime_ns)
  payload=stream.read(size+1);post=os.fstat(stream.fileno())
 end=p.lstat();assert (post.st_dev,post.st_ino,post.st_size,post.st_mtime_ns,post.st_ctime_ns)==(pre.st_dev,pre.st_ino,pre.st_size,pre.st_mtime_ns,pre.st_ctime_ns)==(end.st_dev,end.st_ino,end.st_size,end.st_mtime_ns,end.st_ctime_ns)
 assert len(payload)==size and hashlib.sha256(payload).hexdigest()==digest
 return payload
